deck_style.css:
.dk-stat {
  font: 600 var(--fs-stat)/1 var(--font-sans);
  color: var(--brand-core-primary);
}
.dk-stat-label { font-size: var(--fs-caption); color: var(--brand-core-muted); }
.dk-note { font-size: var(--fs-body); color: var(--brand-core-text); }
.dk-callout {
  border-left: 4px solid var(--brand-accents-amber);
  padding: 16px 24px;
  background: var(--brand-core-surface);
}
